-- One Facility 9C.7-B2 | Daily event trends for ONE client and ONE FM relationship.
-- D8-D15 approved 2026-11-10. No historical state snapshots or SLA claims.
-- Migration filename generated by Supabase CLI v2.79.0 on GitHub Actions.
-- Additive, no data writes and no change to the V1 client metrics RPC.

DO $preflight$
BEGIN
  IF to_regprocedure('public.get_facility_management_client_metrics(uuid,uuid)') IS NULL
     OR to_regclass('public.work_orders') IS NULL
     OR to_regclass('public.requests') IS NULL
     OR to_regclass('public.facility_management_permissions') IS NULL
  THEN
    RAISE EXCEPTION '9C.7-B2 requires the validated 9C.7-B1 delegated metrics schema';
  END IF;
END $preflight$;

CREATE OR REPLACE FUNCTION public.get_facility_management_client_trends(
  _client_organization_id uuid,
  _relationship_id uuid,
  _start_date date,
  _end_date date,
  _time_zone text
) RETURNS jsonb
LANGUAGE plpgsql STABLE SECURITY DEFINER
SET search_path TO ''
SET statement_timeout TO '5s'
AS $function$
DECLARE
  v_authorized boolean := false;
  v_can_requests boolean := false;
  v_can_work_orders boolean := false;
  v_start_utc timestamptz;
  v_end_utc_exclusive timestamptz;
  v_as_of timestamptz := pg_catalog.statement_timestamp();
  v_work_orders jsonb := NULL;
  v_requests jsonb := NULL;
BEGIN
  -- Never infer access from the user-selected client. Every request must
  -- prove a live FM/client relation, assigned active FM manager and the
  -- explicit reporting permission on THAT relationship.
  SELECT EXISTS (
    SELECT 1
    FROM public.organization_relationships rel
    JOIN public.organizations client
      ON client.id=rel.source_organization_id
      AND client.organization_type='client_company'
      AND client.status='active'
    JOIN public.organizations fm
      ON fm.id=rel.target_organization_id
      AND fm.organization_type='facility_manager'
      AND fm.status='active'
    JOIN public.organization_members member
      ON member.organization_id=fm.id
      AND member.user_id=auth.uid()
      AND member.is_active
      AND member.role IN ('owner','admin','manager')
    JOIN public.facility_management_relationship_members assigned
      ON assigned.relationship_id=rel.id
      AND assigned.organization_member_id=member.id
    JOIN public.facility_management_permissions grant_reports
      ON grant_reports.relationship_id=rel.id
      AND grant_reports.permission='reports.view'
    WHERE rel.id=_relationship_id
      AND rel.source_organization_id=_client_organization_id
      AND rel.relationship_type='facility_management'
      AND rel.status='active'
      AND auth.uid() IS NOT NULL
  ) INTO v_authorized;

  IF NOT v_authorized THEN
    -- No difference between unknown, suspended, foreign, or revoked scope.
    RAISE EXCEPTION 'Not authorized to view delegated client trends'
      USING ERRCODE='42501';
  END IF;

  IF _start_date IS NULL
     OR _end_date IS NULL
     OR NOT pg_catalog.isfinite(_start_date)
     OR NOT pg_catalog.isfinite(_end_date)
     OR _end_date < _start_date
     OR _end_date - _start_date > 365
  THEN
    RAISE EXCEPTION 'Select an inclusive date range between 1 and 366 days'
      USING ERRCODE='22023';
  END IF;

  -- 9C.7-B2 pilot ONLY: organization timezone is not in the schema yet.
  -- This explicit allowlist avoids pretending all clients are in Lima.
  IF _time_zone IS DISTINCT FROM 'America/Lima' THEN
    RAISE EXCEPTION 'Time zone is not enabled for this reporting pilot'
      USING ERRCODE='22023';
  END IF;

  -- Inclusive UI end date becomes the NEXT local midnight, exclusive UTC.
  -- Filtering and bucketing use the SAME timezone, avoiding UTC-day drift.
  v_start_utc := _start_date::timestamp AT TIME ZONE _time_zone;
  v_end_utc_exclusive := (_end_date::timestamp + interval '1 day') AT TIME ZONE _time_zone;

  SELECT EXISTS (
    SELECT 1 FROM public.facility_management_permissions p
    WHERE p.relationship_id=_relationship_id
      AND p.permission='requests.view'
  ) INTO v_can_requests;

  SELECT v_can_requests AND EXISTS (
    SELECT 1 FROM public.facility_management_permissions p
    WHERE p.relationship_id=_relationship_id
      AND p.permission='work_orders.view'
  ) INTO v_can_work_orders;

  IF v_can_work_orders THEN
    WITH events AS (
      SELECT pg_catalog.timezone(_time_zone, wo.created_at)::date AS event_day,
             count(*)::bigint AS created_count, 0::bigint AS completed_count
      FROM public.work_orders wo
      WHERE wo.client_organization_id=_client_organization_id
        AND wo.created_at >= v_start_utc
        AND wo.created_at < v_end_utc_exclusive
        AND EXISTS (
          SELECT 1 FROM public.requests req
          WHERE req.id=wo.request_id
            AND req.organization_id=_client_organization_id
            AND req.status NOT IN ('draft','anulado')
        )
      GROUP BY 1
      UNION ALL
      SELECT pg_catalog.timezone(_time_zone, wo.completed_at)::date AS event_day,
             0::bigint AS created_count, count(*)::bigint AS completed_count
      FROM public.work_orders wo
      WHERE wo.client_organization_id=_client_organization_id
        AND wo.completed_at IS NOT NULL
        AND wo.completed_at >= v_start_utc
        AND wo.completed_at < v_end_utc_exclusive
        AND EXISTS (
          SELECT 1 FROM public.requests req
          WHERE req.id=wo.request_id
            AND req.organization_id=_client_organization_id
            AND req.status NOT IN ('draft','anulado')
        )
      GROUP BY 1
    ),
    totals AS (
      SELECT event_day,
             pg_catalog.sum(created_count) AS created_count,
             pg_catalog.sum(completed_count) AS completed_count
      FROM events GROUP BY event_day
    )
    SELECT pg_catalog.jsonb_build_object(
      'daily',pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'date',s.day::date::text,
          'created',pg_catalog.coalesce(t.created_count,0),
          'completed',pg_catalog.coalesce(t.completed_count,0)
        ) ORDER BY s.day)
    ) INTO v_work_orders
    FROM pg_catalog.generate_series(
      _start_date::timestamp, _end_date::timestamp, interval '1 day'
    ) AS s(day)
    LEFT JOIN totals t ON t.event_day=s.day::date;
  END IF;

  IF v_can_requests THEN
    WITH events AS (
      SELECT pg_catalog.timezone(_time_zone, req.created_at)::date AS event_day,
             count(*)::bigint AS created_count
      FROM public.requests req
      WHERE req.organization_id=_client_organization_id
        AND req.created_at >= v_start_utc
        AND req.created_at < v_end_utc_exclusive
      GROUP BY 1
    )
    SELECT pg_catalog.jsonb_build_object(
      'daily',pg_catalog.jsonb_agg(
        pg_catalog.jsonb_build_object(
          'date',s.day::date::text,
          'created',pg_catalog.coalesce(e.created_count,0)
        ) ORDER BY s.day)
    ) INTO v_requests
    FROM pg_catalog.generate_series(
      _start_date::timestamp, _end_date::timestamp, interval '1 day'
    ) AS s(day)
    LEFT JOIN events e ON e.event_day=s.day::date;
  END IF;

  -- No entity IDs, notes, money, technician/provider details, SLA or
  -- fabricated historic open/overdue statuses. Null means no domain grant.
  RETURN pg_catalog.jsonb_build_object(
    'as_of',v_as_of,
    'start_date',_start_date::text,
    'end_date',_end_date::text,
    'time_zone',_time_zone,
    'availability',pg_catalog.jsonb_build_object(
      'work_orders',v_can_work_orders,
      'requests',v_can_requests
    ),
    'work_orders',v_work_orders,
    'requests',v_requests
  );
END
$function$;

-- A SECURITY DEFINER RPC is narrowly granted and checks auth.uid() itself.
REVOKE ALL ON FUNCTION public.get_facility_management_client_trends(
  uuid,uuid,date,date,text
) FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.get_facility_management_client_trends(
  uuid,uuid,date,date,text
) TO authenticated;
